test('Given all thirteen compiler sources, when public Seed and three complete JS generations compile, then source artifacts reach a fixed point',async()=>{const files=(await readdir('bootstrap/compiler')).filter(f=>f.endsWith('.eli')).sort();assert.equal(files.length,13);let compiler=b.compiler;const previous=new Map();for(const file of files)previous.set(file,await readFile(resolve(directory,'bootstrap',file.replace(/\.eli$/,'.mjs')),'utf8'));const seedDir=resolve(directory,'reader-public-seed');await mkdir(seedDir);const seedFile=resolve(seedDir,'reader.mjs'),seed=spawnSync(resolve('bin/eliscript-seed'),['--source-map','--output',seedFile,resolve('bootstrap/compiler/reader.eli')],{encoding:'utf8',timeout:30000});assert.equal(seed.status,0,seed.stderr);assert.equal(await readFile(seedFile,'utf8'),previous.get('reader.eli'));for(let generation=2;generation<=3;generation++){const output=resolve(directory,'reader-g'+generation);await mkdir(output);for(const file of files){const path=resolve('bootstrap/compiler/'+file),source=await readFile(path,'utf8'),p=compiler.compile_ir_string(source,path),saved=JSON.stringify(p),generated=file.replace(/\.eli$/,'.mjs'),emitted=compiler.emit_ir_string_with_source_map(p,source,generated,relative(output,path)),javascript=emitted.javascript+'//# sourceMappingURL='+generated+'.map\n';assert.equal(JSON.stringify(p),saved);assert.equal(javascript,previous.get(file),'generation '+generation+': '+file);await writeFile(resolve(output,generated),javascript);await writeFile(resolve(output,generated+'.map'),emitted.sourceMap);}compiler=await import(pathToFileURL(resolve(output,'compiler.mjs')).href);}},30000);
test('Given represented string cursor fields, when independent WASM scans, then raw JavaScript += preserves concatenation instead of numeric stepping',()=>{const{a}=instance(withSupport());for(const[source,index,offset,line,column]of[[' \tx',0,'10','2','7'],['\n x',0,'10','2','7'],[' \tx','0','10','2','7']]){const expected={source,index,offset,line,column};skip(expected,whitespace);const input=state(a,source,index,offset,line,column);assert.equal(a.invoke('reader-skip',[input]),null);assert.deepEqual(readState(a,input),expected);a.release(input);a.collect();}finish(a,[]);});

test('Given extra effectful arguments, when each original helper ignores them, then caller effects finish once before state snapshots',()=>{const{a}=instance(withSupport()),log=a.sourceArray([]);assert.equal(a.invoke('reader-extra-predicate',[log]),true);assert.equal(a.length(log),2);for(let i=0;i<2;i++){const value=a.get(log,i);assert.equal(a.readNumber(value),i);a.release(value);}for(const mode of['skip','token']){const input=state(a,'ab '),trace=a.sourceObject({called:false}),begin=start(a,0),expected={source:'ab ',index:0,offset:11,line:3,column:7},effects={called:false};let count=0;const extra=()=>{count++;expected.index=1;return 1;},mark=()=>{count++;effects.called=true;return true;};let output;if(mode==='skip'){assert.equal(skip(expected,whitespace,extra(),mark()),null);output=a.invoke('reader-extra-skip',[input,trace]);assert.equal(output,null);}else{const text=token(expected,{index:0},delimiter,extra(),mark());output=a.invoke('reader-extra-token',[input,begin,trace]);assert.equal(a.readString(output),text);}assert.equal(count,2);assert.equal(effects.called,true);assert.deepEqual(readState(a,input),expected);const key=a.string('called');assert.equal(a.objectGet(trace,key),true);for(const value of[input,trace,begin,output,key])a.release(value);}finish(a,[log]);});
